def summarize_spans(events):
    if not isinstance(events, list):
        raise ValueError("events must be a list")

    allowed_levels = {"debug", "info", "warning", "error"}
    stacks = {}
    result = []
    previous_tick = -1

    for event in events:
        if not isinstance(event, dict) or set(event) != {"name", "kind", "tick", "level"}:
            raise ValueError("invalid event")
        name = event["name"]
        kind = event["kind"]
        tick = event["tick"]
        level = event["level"]
        if not isinstance(name, str) or not name:
            raise ValueError("invalid name")
        if kind not in {"begin", "finish"}:
            raise ValueError("invalid kind")
        if type(tick) is not int or tick < 0 or tick < previous_tick:
            raise ValueError("invalid tick ordering")
        if level not in allowed_levels:
            raise ValueError("invalid level")
        previous_tick = tick

        stack = stacks.setdefault(name, [])
        if kind == "begin":
            stack.append((tick, level))
        else:
            if not stack:
                raise ValueError("finish without begin")
            start, start_level = stack.pop(0)
            result.append({
                "name": name,
                "start": start,
                "end": tick,
                "elapsed": tick - start,
                "start_level": start_level,
                "end_level": level,
            })

    if any(stack for stack in stacks.values()):
        raise ValueError("unmatched begin")
    return result

